// Package regions knows country names, map positions and the city codes
// VPN providers put in config file names, so imported configs can be
// placed on the map automatically.
package regions

import (
	_ "embed"
	"encoding/json"
	"path/filepath"
	"regexp"
	"strings"
	"unicode"
)

// Country is one entry of countries.json (generated by tools/mapgen).
type Country struct {
	Code string  `json:"code"`
	Name string  `json:"name"`
	Lat  float64 `json:"lat,omitempty"`
	Lon  float64 `json:"lon,omitempty"`
	X    float64 `json:"x,omitempty"`
	Y    float64 `json:"y,omitempty"`
}

//go:embed countries.json
var countriesJSON []byte

var (
	byCode    = map[string]Country{}
	Countries []Country
)

func init() {
	if err := json.Unmarshal(countriesJSON, &Countries); err != nil {
		panic("regions: bad countries.json: " + err.Error())
	}
	for _, c := range Countries {
		byCode[c.Code] = c
	}
}

// Lookup returns the country for an ISO 3166-1 alpha-2 code.
func Lookup(code string) (Country, bool) {
	c, ok := byCode[strings.ToUpper(code)]
	return c, ok
}

// City is a well-known VPN server location.
type City struct {
	Code    string  `json:"code"` // the code providers use in file and host names
	Name    string  `json:"name"`
	Country string  `json:"country"`
	Lat     float64 `json:"lat"`
	Lon     float64 `json:"lon"`
}

