var cityByKey = map[string]City{}

func init() {
	for _, c := range Cities {
		cityByKey[c.Country+"-"+c.Code] = c
		if _, ok := cityByKey["*-"+c.Code]; !ok {
			cityByKey["*-"+c.Code] = c
		}
	}
}

// FindCity looks up a city by name within a country (case-insensitive).
func FindCity(country, name string) (City, bool) {
	for _, c := range Cities {
		if c.Country == country && strings.EqualFold(c.Name, name) {
			return c, true
		}
	}
	return City{}, false
}

var providerWords = []string{
	"mullvad", "proton", "protonvpn", "ivpn", "airvpn", "windscribe", "surfshark",
	"nord", "nordvpn", "pia", "ovpn", "azire", "torguard", "privado", "hide", "cryptostorm",
	"meridian", "wg", "wireguard",
}

var tokenSplit = regexp.MustCompile(`[^A-Za-z0-9]+`)

// Guess is a best guess at where a config exits.
type Guess struct {
	Country string
	City    string
	Source  string // "filename" or "endpoint"
}

// Detect guesses the country and city from a config's file name and its
// endpoint host name (for example "mullvad-nl-ams-wg-001.conf" or
// "us-nyc-wg-301.relays.mullvad.net").
func Detect(filename, endpointHost string) (Guess, bool) {
	base := strings.TrimSuffix(filepath.Base(filename), filepath.Ext(filename))
	if g, ok := detectTokens(base); ok {
		g.Source = "filename"
		return g, true
	}
	if endpointHost != "" && !isIP(endpointHost) {
		labels := strings.Split(endpointHost, ".")
		if len(labels) > 2 {
			if g, ok := detectTokens(strings.Join(labels[:len(labels)-2], "-")); ok {
				g.Source = "endpoint"
				return g, true
			}
		}
	}
	return Guess{}, false
}

func isIP(s string) bool {
	return strings.Count(s, ":") >= 2 || regexp.MustCompile(`^[0-9.]+$`).MatchString(s)
}

func detectTokens(s string) (Guess, bool) {
	raw := tokenSplit.Split(s, -1)
	lower := strings.ToLower(s)
	hasProvider := false
	for _, w := range providerWords {
		if strings.Contains(lower, w) {
			hasProvider = true
			break
		}
	}
	for i, tok := range raw {
		if len(tok) < 2 {
			continue
		}
		// "nl1", "us12": a country code followed by a server number.
		cc := strings.TrimRightFunc(tok, unicode.IsDigit)
		if len(cc) != 2 {
			continue
		}
		code := strings.ToUpper(cc)
		if _, ok := byCode[code]; !ok {
			continue
		}
		var next string
		if i+1 < len(raw) {
			next = strings.ToLower(strings.TrimRightFunc(raw[i+1], unicode.IsDigit))
		}
		if city, ok := cityByKey[code+"-"+next]; ok {
			return Guess{Country: code, City: city.Name}, true
		}
		upper := cc == strings.ToUpper(cc)
		if hasProvider || upper || len(tok) > 2 {
			return Guess{Country: code}, true
		}
	}
	return Guess{}, false
}
